mapper.select:
SELECT r.id, r.user_id, r.character_id, r.fortune_id, r.fortune_score AS luck_score, r.mood, r.wish_topic, r.message, r.draw_time, c.id AS c_id, c.english_name, NULL AS japanese_name, c.anime_title, c.role_type AS archetype, c.energy AS element, c.image_url, c.tags AS quote, c.popularity_score AS popularity, f.id AS f_id, f.summary AS title, f.level_name, f.advice, f.lucky_color, f.lucky_item FROM sekai_Draw_lots_record r JOIN sekai_Draw_lots_character c ON r.character_id = c.id JOIN sekai_Draw_lots_fortune f ON r.fortune_id = f.id WHERE r.user_id = #{userId}
AND ( c.english_name LIKE CONCAT('%', #{keyword}, '%') OR c.anime_title LIKE CONCAT('%', #{keyword}, '%') OR r.wish_topic LIKE CONCAT('%', #{keyword}, '%') OR r.message LIKE CONCAT('%', #{keyword}, '%') )
AND r.mood = #{mood}
AND r.fortune_score >= #{minScore}
ORDER BY r.draw_time DESC, r.id DESC LIMIT #{limit}
